def resolve_app_path(env_name: str, fallback: Path) -> Path:
    configured = os.getenv(env_name)
    if not configured:
        return fallback

    candidate = Path(configured).expanduser()
    return candidate if candidate.is_absolute() else (BASE_DIR / candidate).resolve()


