def normalize_mindmap_studio_side(value: str | None, *, fallback: str = "right") -> str:
    candidate = str(value or "").strip().lower()
    if candidate in {"left", "right", "center"}:
        return candidate
    if fallback in {"left", "right", "center"}:
        return fallback
    return "right"


