    note["title"] = request.form.get("note_title", "").strip()[:120]
    note["content_html"] = content_html
    note["content_text"] = content_text
    note["tags"] = normalize_tag_list(request.form.get("note_tags", ""))
    note["updated_at"] = now_iso()

