@app.get("/stocks/<symbol>/files/<file_id>/preview")
def preview_stock_file(symbol: str, file_id: str):
    store = load_stock_store()
    symbol = require_stock_symbol(symbol)
    file_record = get_stock_file_record(store, symbol, file_id)
